{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
matches = []
for a in mw.findChildren(QAction):
    t = a.text().replace('&','')
    if ('地物' in t and '追加' in t) or 'AddFeature' in a.objectName() or a.objectName() in ('mActionNewFeature','mActionAddFeature'):
        parents = []
        try:
            for o in a.associatedObjects():
                if isinstance(o, QMenu):
                    parents.append('menu:' + (o.title() or o.objectName()))
                else:
                    parents.append(type(o).__name__)
        except Exception:
            pass
        matches.append({'objectName': a.objectName(), 'text': t, 'enabled': a.isEnabled(), 'checkable': a.isCheckable(), 'checked': a.isChecked(), 'parents': parents})
result = matches"}
